    Script('OP_PUSHDATA1 5 0x1010101010').isPushOnly().should.equal(true)
    Script('OP_PUSHDATA2 5 0x1010101010').isPushOnly().should.equal(true)
    Script('OP_PUSHDATA4 5 0x1010101010').isPushOnly().should.equal(true)
